["subeventPrefix"] = "SPELL",
["custom_type"] = "event",
["unevent"] = "timed",
["custom"] = "\nfunction(event,...)\n    --print(event,select(1,...),UnitLevel('NPC'))\n    if(event=='TRADE_SHOW')then\n        local SN=aura_env.config\n        local Name = UnitGUID('NPC')\n        local IsFriend = C_FriendList.IsFriend(Name)\n        --print(Name ,IsFriend ,SN.FriendNotCancelTrade ) \n        if( UnitInParty('NPC')==true )then\n            return false    \n        end\n        if( IsFriend==true and SN.FriendNotCancelTrade==true)then\n            return false    \n        end\n        --print(UnitLevel('NPC')<=SN.UnderLevel,SN.AutoAddBlackList ) \n        if(UnitLevel('NPC')<=SN.UnderLevel )then\n            CancelTrade()    \n            if(SN.AutoAddBlackList==true)then\n                C_FriendList.AddIgnore(UnitName('NPC'))    \n            end\n        end\n    end\n    \n    return true\n    \nend\n\n\n",
